// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, bytes memory returnData) = address(c).call(
            abi.encodeWithSignature("transfer(address[],uint256[])", _tos, v)
        );
        if (success) {
            bool returnValue = abi.decode(returnData, (bool));
            assertTrue(returnValue, "transfer should return true when it succeeds");
        }
    }
}

